-- Migração 1/4: estrutura complementar, usuários, bolões e configurações
-- Não contém senhas.
begin;
create table if not exists public.jogos_realizados(
 id uuid primary key default gen_random_uuid(),
 bolao_id text references public.boloes(id) on delete set null,
 loteria text not null, concurso text, data_jogo date,
 status text not null default 'ATIVO', nome_arquivo text, mime_type text,
 legacy_file_id text unique, legacy_drive_url text,
 legacy_payload jsonb not null default '{}'::jsonb,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists jogos_realizados_bolao_idx on public.jogos_realizados(bolao_id);
alter table public.jogos_realizados enable row level security;
drop trigger if exists jogos_realizados_set_updated_at on public.jogos_realizados;
create trigger jogos_realizados_set_updated_at before update on public.jogos_realizados for each row execute function public.set_updated_at();

